"""Consolidated review of saved arrays only; no model fitting or new attribution passes."""
from pathlib import Path
import hashlib,json,itertools
import numpy as np,pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
B=Path(__file__).resolve().parents[1];ROOT=B.parents[2];P=ROOT/'news-enhanced-crypto-research/phase1';R=B/'review';R.mkdir(exist_ok=True);F=B/'figures';F.mkdir(exist_ok=True)
plan=json.loads((B/'FULL_PROTOCOL.json').read_text());cfg=json.loads((P/'E1B/CONFIG.json').read_text());d=pd.read_csv(cfg['dataset'],float_precision='round_trip');train=np.load(P/'main_train.npy');test=np.load(P/'main_evaluation.npy');features=cfg['features'];ni=np.array([f in cfg['news_features'] for f in features]);checks=[];global_rows=[];groups=[];originrows=[];residual_rows=[];arrays=[];lags=[];rankvectors=[]
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
for seed in plan['seeds']:
 assert sha(P/f'E1B/runs/E1B_seed{seed}/best.pt')==plan['checkpoint_hashes'][str(seed)]
 for bg in plan['backgrounds']:
  p=B/f'results/E1B_seed{seed}_background{bg}.npz';z=np.load(p);a=z['values'];rows=z['origin_rows'];refs=z['background_rows'];delta=z['output_difference'];res=z['residual'];tol=1e-5+.01*abs(delta);old=np.load(B.parent/f'results/E1B_seed{seed}_background{bg}_ATTRIBUTIONS.npz')
  assert a.shape==(1000,30,25) and np.isfinite(a).all();assert np.array_equal(z['features'],features);assert np.array_equal(rows,old['origin_rows']);assert np.array_equal(refs,old['background_rows']);assert np.isin(refs,train).all() and np.isin(rows,test).all();assert set(z['quadrature_points']).issubset({64,128,256});assert np.max(abs(delta-a.sum((1,2))-res))<1e-7
  if arrays:assert np.array_equal(rows,arrays[0][2])
  arrays.append((seed,bg,rows,a,delta,tol,res));imp=abs(a).sum(1).mean(0);share=100*imp[ni].sum()/imp.sum();ok=abs(res)<=tol
  valid=abs(a[ok]).sum(1).mean(0);validshare=100*valid[ni].sum()/valid.sum();oldimp=abs(old['values']).sum(1).mean(0);oldshare=100*oldimp[ni].sum()/oldimp.sum();vec=pd.Series(imp).rank().to_numpy();rankvectors.append((seed,bg,vec))
  checks.append(dict(seed=seed,background=bg,news_percent=share,technical_percent=100-share,news_percent_passing_only=validshare,old_news_percent=oldshare,mean_abs_residual=float(abs(res).mean()),max_abs_residual=float(abs(res).max()),failed_tolerance=int((~ok).sum()),q64=int((z['quadrature_points']==64).sum()),q128=int((z['quadrature_points']==128).sum()),q256=int((z['quadrature_points']==256).sum()),npz_sha256=sha(p)))
  for j,f in enumerate(features):global_rows.append(dict(seed=seed,background=bg,feature=f,group='news' if ni[j] else 'technical',mean_absolute_attribution=float(imp[j])))
  x=d.iloc[rows];threshold=d.iloc[train].volatility.quantile(.9)
  masks={'all':np.ones(1000,bool),'current_hour_news':x.direct_news_present.to_numpy().astype(bool),'no_current_hour_article':~x.direct_news_present.to_numpy().astype(bool),'positive_XRP_news':((x.direct_stance>0)&(x.direct_specificity>0)).to_numpy(),'negative_XRP_news':((x.direct_stance<0)&(x.direct_specificity>0)).to_numpy(),'high_volatility':(x.volatility>threshold).to_numpy()}
  for name,mask in masks.items():
   if not mask.any():continue
   v=abs(a[mask]).sum(1).mean(0);groups.append(dict(seed=seed,background=bg,group=name,n=int(mask.sum()),mean_abs_news=float(v[ni].sum()),news_percent=float(100*v[ni].sum()/v.sum())))
  for j in range(1000):residual_rows.append(dict(seed=seed,background=bg,origin_row=int(rows[j]),output_difference=float(delta[j]),residual=float(res[j]),tolerance=float(tol[j]),quadrature_points=int(z['quadrature_points'][j]),passes=bool(ok[j])))
  for lag in range(30):
   v=abs(a[:,lag,:]).mean(0);lags.append(dict(seed=seed,background=bg,lag_hours=lag-29,technical_abs=float(v[~ni].sum()),news_abs=float(v[ni].sum())))
checks=pd.DataFrame(checks);g=pd.DataFrame(global_rows);group=pd.DataFrame(groups);lag=pd.DataFrame(lags);checks.to_csv(R/'PRECISION_AND_CONTRIBUTIONS.csv',index=False);g.to_csv(R/'GLOBAL_IMPORTANCE_ALL_RUNS.csv',index=False);group.to_csv(R/'FEATURE_CONDITIONED_SUBGROUPS.csv',index=False);lag.to_csv(R/'TEMPORAL_ATTRIBUTION.csv',index=False);pd.DataFrame(residual_rows).to_csv(R/'EXPLANATION_RESIDUALS.csv',index=False)
rank=[]
for (s,b,v),(s2,b2,v2) in itertools.combinations(rankvectors,2):rank.append(dict(seed1=s,background1=b,seed2=s2,background2=b2,spearman=float(np.corrcoef(v,v2)[0,1])))
pd.DataFrame(rank).to_csv(R/'RANK_STABILITY.csv',index=False)
pilot=[]
for q in [16,32,64]:
 z=np.load(B/f'pilot_q{q}.npz');pilot.append({'quadrature':q,'mean_abs_residual':float(abs(z['residual']).mean()),'max_abs_residual':float(abs(z['residual']).max())})
pd.DataFrame(pilot).to_csv(R/'PILOT_CONVERGENCE.csv',index=False)
meanimp=g.groupby('feature').mean_absolute_attribution.mean().reindex(features);pooledshare=100*meanimp.to_numpy()[ni].sum()/meanimp.sum();seedsummary=checks.groupby('seed')[['news_percent','technical_percent']].mean();seedsummary.to_csv(R/'SEED_CONTRIBUTIONS.csv')
summary={'completed_passes':len(checks),'seeds':5,'backgrounds_per_seed':2,'origins_per_pass':1000,'total_explanations':10000,'failed_tolerance':int(checks.failed_tolerance.sum()),'pass_fraction':float(1-checks.failed_tolerance.sum()/10000),'mean_news_share_equal_pass_weight':float(checks.news_percent.mean()),'mean_technical_share_equal_pass_weight':float(checks.technical_percent.mean()),'news_share_range':[float(checks.news_percent.min()),float(checks.news_percent.max())],'news_seed_mean_sd':float(seedsummary.news_percent.std(ddof=1)),'pooled_absolute_attribution_news_share':float(pooledshare),'maximum_passing_only_share_change_pp':float(abs(checks.news_percent-checks.news_percent_passing_only).max()),'global_rank_pairwise_spearman_range':[min(x['spearman'] for x in rank),max(x['spearman'] for x in rank)],'prior_66_2_33_8':'not confirmed for the corrected E1B model and this explanation design','interpretation':'Reference-dependent expected integrated gradients, not exact Shapley values or causal price effects','residual_caveat':'Small additivity residual does not establish convergence of every feature attribution; compensating errors and reference dependence remain possible','no_new_model_or_attribution_inference':True,'checkpoints_unchanged':True,'sample_and_training_backgrounds_match_original':True}
(R/'NUMERICAL_VERIFICATION.json').write_text(json.dumps(summary,indent=2));print(json.dumps(summary,indent=2))
# Figures are derived solely from completed arrays.
fig,axs=plt.subplots(1,2,figsize=(10,5));v=meanimp.sort_values().tail(18);axs[0].barh(v.index,v,color=['#bb6c32' if f in cfg['news_features'] else '#36739b' for f in v.index]);axs[0].set(xlabel='Mean absolute log return attribution',title='Global feature importance');ss=checks.pivot(index='seed',columns='background',values='news_percent');ss.plot.bar(ax=axs[1],rot=0,color=['#36739b','#bb6c32']);axs[1].set(ylabel='News attribution percent',xlabel='Training seed',title='Reference and seed sensitivity');axs[1].axhline(33.8,color='black',ls='--',lw=1,label='Historical claim');axs[1].legend(title='Background',fontsize=8);fig.tight_layout();fig.savefig(F/'GLOBAL_AND_STABILITY.png',dpi=180);plt.close(fig)
fig,axs=plt.subplots(1,2,figsize=(10,3.8));lt=lag.groupby('lag_hours')[['technical_abs','news_abs']].mean();lt.plot(ax=axs[0],color=['#36739b','#bb6c32']);axs[0].set(title='Attribution across the 30 input hours',xlabel='Hours before origin',ylabel='Mean absolute attribution');heat=np.mean([abs(x[3]).mean(0) for x in arrays],axis=0).T;im=axs[1].imshow(heat,aspect='auto',cmap='magma');axs[1].set(xlabel='Input lag oldest to newest',ylabel='Feature index in saved schema',title='Feature and time attribution');fig.colorbar(im,ax=axs[1],shrink=.8);fig.tight_layout();fig.savefig(F/'TEMPORAL.png',dpi=180);plt.close(fig)
fig,axs=plt.subplots(1,2,figsize=(10,3.5));gg=group.groupby('group').agg(value=('mean_abs_news','mean'),n=('n','first'));axs[0].barh(gg.index,gg.value,color='#36739b');axs[0].set(xlabel='Mean absolute news attribution',title='Feature defined subgroups');rr=pd.DataFrame(residual_rows);axs[1].hist(np.log10(np.maximum(abs(rr.residual)/rr.tolerance,1e-8)),bins=45,color='#36739b');axs[1].axvline(0,color='#bb6c32',ls='--');axs[1].set(xlabel='log10 absolute residual divided by tolerance',ylabel='Explanations',title='Numerical completeness check');fig.tight_layout();fig.savefig(F/'SUBGROUP_AND_PRECISION.png',dpi=180);plt.close(fig)
fig,axs=plt.subplots(1,2,figsize=(10,3.2));pp=pd.DataFrame(pilot);axs[0].plot(pp.quadrature,pp.mean_abs_residual,marker='o');axs[0].set(yscale='log',xlabel='Quadrature points',ylabel='Mean absolute residual',title='Fixed 20 origin pilot convergence');checks[['old_news_percent','news_percent']].plot.bar(ax=axs[1],rot=45,color=['#aab5bc','#36739b']);axs[1].set_xticklabels([f'{int(x.seed)} / {int(x.background)}' for _,x in checks.iterrows()]);axs[1].set(ylabel='News attribution percent',xlabel='Seed and background',title='Original and refined estimates');axs[1].legend(['Original MC','Refined']);fig.tight_layout();fig.savefig(F/'CONVERGENCE.png',dpi=180);plt.close(fig)
